package com.google.gson.stream;

import com.google.gson.internal.JsonReaderInternalAccess;
import com.google.gson.internal.bind.JsonTreeReader;
import com.google.gson.stream.JsonReader;
import java.io.*;
import java.io.Closeable;
import java.io.EOFException;
import java.io.IOException;
import java.io.Reader;
import java.io.StringReader;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class JsonReader_nextInt_TriageGen1Test {

    private JsonReader jsonReader;

    @Before
    public void setUp() throws IOException {
        jsonReader = new JsonReader(new StringReader(""));
    }

    @After
    public void tearDown() throws IOException {
        if (jsonReader != null) {
            jsonReader.close();
        }
    }

    @Test(expected = IllegalStateException.class)
    public void testNextInt_UnexpectedToken() throws IOException {
        jsonReader = new JsonReader(new StringReader("invalid"));
        jsonReader.next();
        jsonReader.nextInt();
    }

    @Test(expected = NumberFormatException.class)
    public void testNextInt_LongPrecisionLoss() throws IOException {
        jsonReader = new JsonReader(new StringReader("2147483648"));
        jsonReader.nextInt();
    }

    @Test(expected = NumberFormatException.class)
    public void testNextInt_StringPrecisionLoss() throws IOException {
        jsonReader = new JsonReader(new StringReader("\"2147483648\""));
        jsonReader.nextInt();
    }

    @Test
    public void testNextInt_NormalInteger() throws IOException {
        jsonReader = new JsonReader(new StringReader("123"));
        assertEquals(123, jsonReader.nextInt());
    }

    @Test
    public void testNextInt_NegativeInteger() throws IOException {
        jsonReader = new JsonReader(new StringReader("-123"));
        assertEquals(-123, jsonReader.nextInt());
    }

    @Test
    public void testNextInt_QuotedInteger() throws IOException {
        jsonReader = new JsonReader(new StringReader("\"123\""));
        assertEquals(123, jsonReader.nextInt());
    }

    @Test
    public void testNextInt_DoubleValueAsInt() throws IOException {
        jsonReader = new JsonReader(new StringReader("123.0"));
        assertEquals(123, jsonReader.nextInt());
    }

    @Test(expected = NumberFormatException.class)
    public void testNextInt_DoubleValuePrecisionLoss() throws IOException {
        jsonReader = new JsonReader(new StringReader("123.456"));
        jsonReader.nextInt();
    }

    @Test(expected = NumberFormatException.class)
    public void testNextInt_QuotedDoubleValuePrecisionLoss() throws IOException {
        jsonReader = new JsonReader(new StringReader("\"123.456\""));
        jsonReader.nextInt();
    }

    @Test(expected = NumberFormatException.class)
    public void testNextInt_QuotedNonNumericString() throws IOException {
        jsonReader = new JsonReader(new StringReader("\"abc\""));
        jsonReader.nextInt();
    }
}
